
from typing_extensions import Annotated, List

from ...common import BaseRequestModel
from ....utils.common_types import Source

class DiscoveryRequestRefinementWriterAgentRequest(BaseRequestModel):
    input: str
    topic: str
    target: str
    aimie_question: str
    bob_retort: str
    hearing_type: str
    location: str


class DiscoveryRequestRefinementWriterAgentOutput(BaseRequestModel):
    refinement_rationale: str
    refine_questions: Annotated[
        List[str],
        ...,
        "The refined questions generated by the agent"
    ]
    sources: Annotated[
        List[Source],
        ...,
        "The sources used to generate the refined questions."
    ]